def sigmoid(value):
    tail = exp(-abs(value))
    return 1 / (1 + tail) if value >= 0 else tail / (1 + tail)


def softplus(value):
    return max(value, 0) + log1p(exp(-abs(value)))


def conductance(source, connections, destination):
    total = pull = 0.0
    for value, edges in zip(source, connections):
        strength, slope, midpoint, reversal = edges[destination]
        active = softplus(strength) * sigmoid(slope * (value - midpoint))
        total += active
        pull += active * reversal
    return total, pull


def probability(rows, gaps):
    w = WEIGHTS
    units = range(8)
    state = [0.0] * 8
    leak = [softplus(value) + 1e-6 for value in w["leak"]]
    capacity = [softplus(value) + 1e-6 for value in w["capacitance"]]
    for (_, readings, _), elapsed in zip(rows, gaps):
        if not isfinite(elapsed) or not 0 < elapsed <= 5:
            raise ValueError("Elapsed time must be within (0, 5] minutes")
        sensors = [(v - mean) / scale for v, mean, scale in zip(readings, MEAN, SCALE)]
        sensory = [conductance(sensors, w["sensory"], j) for j in units]
        dt = elapsed / 6
        for _ in range(6):
            updated = []
            for j in units:
                sensed, sensory_pull = sensory[j]
                recurrent, recurrent_pull = conductance(state, w["recurrent"], j)
                total = leak[j] + sensed + recurrent
                pull = leak[j] * w["bias"][j] + sensory_pull + recurrent_pull
                updated.append((capacity[j] * state[j] + dt * pull)
                               / (capacity[j] + dt * total))
            state = updated
    logit = w["readout.bias"][0] + sum(a * b for a, b in zip(w["readout.weight"][0], state))
    return sigmoid(logit)


